public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(nums, 0, res);
    return res;
}

private void backtrack(int[] nums, int start, List<List<Integer>> res) {
    if (start == nums.length) {
        List<Integer> cur = new ArrayList<>();
        for (int num : nums) {
            cur.add(num);
        }
        res.add(cur);
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        backtrack(nums, start + 1, res);
        swap(nums, start, i);
    }
}

private void swap(int[] a, int i, int j) {
    int temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}

public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int maxLen = 0;
    int n = strings.size();
    int firstLen = first.length();
    for (int i = 0; i < firstLen; i++) {
        for (int j = i + 1; j <= firstLen; j++) {
            String sub = first.substring(i, j);
            int len = sub.length();
            if (len <= maxLen) {
                continue;
            }
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int k = 1; k < n; k++) {
                String s = strings.get(k);
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                maxLen = len;
            }
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    int n = grid.length;
    if (n == 0) return 0;
    int m = grid[0].length;
    if (m == 0) return 0;
    boolean[][] visited = new boolean[n][m];
    int deposits = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    int maxSize = n * m;
    int[] stackR = new int[maxSize];
    int[] stackC = new int[maxSize];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                deposits++;
                int top = 0;
                visited[i][j] = true;
                stackR[top] = i;
                stackC[top] = j;
                top++;
                while (top > 0) {
                    top--;
                    int r = stackR[top];
                    int c = stackC[top];
                    for (int k = 0; k < 8; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                            if (grid[nr][nc] == '@' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stackR[top] = nr;
                                stackC[top] = nc;
                                top++;
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

