public String sortString(String s) {
    int[] freq = new int[256];
    for (char ch : s.toCharArray()) {
        freq[ch]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int processed = 0;
    int total = s.length();
    while (processed < total) {
        // Ascending pass: from smallest to largest
        for (int i = 0; i < 256; i++) {
            while (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                processed++;
            }
        }
        // Descending pass: from largest to smallest
        for (int i = 255; i >= 0; i--) {
            while (freq[i] > 0) {
                sb.append((char) i);
                freq[i]--;
                processed++;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    if (totalSum < 0) {
        // The DP approach below relies on non‑negative sums. If negative values are present,
        // fallback to a recursive search.
        return splitArraySameAverageRecursive(nums, totalSum, n);
    }
    // DP: dp[size][sum] is true if a subset of 'size' elements can reach 'sum'.
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int size = n - 1; size >= 0; size--) {
            for (int sum = 0; sum <= totalSum - num; sum++) {
                if (dp[size][sum]) {
                    dp[size + 1][sum + num] = true;
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long scaled = (long) totalSum * k;
        if (scaled % n != 0) {
            continue;
        }
        int target = (int) (scaled / n);
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

