public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0; // start at step 1 and climb directly to the top
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    // Morse code mapping for the 26 letters of the alphabet
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.", "---",".--.",
                      "--.-",".-.", "...","-","..-","...-",".--","-..-","-.--","--..."};

    if (words == null || words.length == 0) {
        return 0;
    }

    java.util.Set<String> unique = new java.util.HashSet<>();

    for (String word : words) {
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (idx >= 0 && idx < 26) {
                sb.append(morse[idx]);
            }
        }
        unique.add(sb.toString());
    }

    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;          // the only binary string of length 0 is the empty string
    int n = s.length();
    if (n < k) return false;          // impossible to contain all codes if s is shorter than k

    int totalCodes = 1 << k;          // total possible binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;        // mask to keep only k bits

    int value = 0;
    // Build initial value for the first window of size k
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    seen[value] = true;
    int count = 1;

    // Slide the window over the rest of the string
    for (int i = k; i < n; i++) {
        // Shift left, drop the highest bit, add the new bit
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == totalCodes) return true; // early exit if all codes seen
        }
    }
    return count == totalCodes;
}

