public int minInsertions(String s) {
    int insertions = 0;
    int left = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            left++;
        } else { // c == ')'
            if (left > 0) {
                left--;
            } else {
                insertions++; // need to insert a '(' before this ')'
            }
        }
    }
    return insertions + left; // add missing ')' for all unmatched '('
}

