public String getSmallestString(int n, int k) {
    char[] arr = new char[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 'a';
    }
    int extra = k - n; // amount of value still needed beyond all 'a's
    for (int i = n - 1; i >= 0 && extra > 0; i--) {
        int add = Math.min(25, extra); // 'z' can only add 25 to 'a'
        arr[i] = (char) ('a' + add);
        extra -= add;
    }
    return new String(arr);
}

