public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            if (((num >> i) & 1) == 1) {
                bitCount++;
            }
        }
        if (bitCount % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = (long) num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer((int) next);
            }
        }
        if (lastDigit < 9) {
            long next = (long) num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer((int) next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long k = 1; k <= n; k *= 10) {
        long high = n / (k * 10);
        long cur = (n / k) % 10;
        long low = n % k;
        if (cur == 0) {
            count += high * k;
        } else if (cur == 1) {
            count += high * k + low + 1;
        } else {
            count += (high + 1) * k;
        }
        // Prevent potential overflow in k multiplication
        if (k > Long.MAX_VALUE / 10) {
            break;
        }
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] hori = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];

    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                hori[i][j] = (j > 0 ? hori[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;

                int localMax = hori[i][j];
                if (vert[i][j] > localMax) localMax = vert[i][j];
                if (diag[i][j] > localMax) localMax = diag[i][j];
                if (anti[i][j] > localMax) localMax = anti[i][j];

                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long val = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (val > 0) {
        sb.append(val % 10);
        val /= 10;
        count++;
        if (val > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    boolean[] visited = new boolean[n];
    int[] result = new int[1];
    dfs(-1, 0, A, visited, result);
    return result[0];
}

private static void dfs(int prevIndex, int depth, int[] A, boolean[] visited, int[] result) {
    int n = A.length;
    if (depth == n) {
        result[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue; // skip duplicates
        if (prevIndex == -1 || isSquare(A[prevIndex] + A[i])) {
            visited[i] = true;
            dfs(i, depth + 1, A, visited, result);
            visited[i] = false;
        }
    }
}

private static boolean isSquare(int sum) {
    int r = (int) Math.sqrt(sum);
    return r * r == sum;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = 0; // number of elements in stack

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top > 0 && currentHeight < heights[stack[top - 1]]) {
            int height = heights[stack[--top]];
            int width = (top == 0) ? i : i - stack[top - 1] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[top++] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int d = 0; d < m + n - 1; d++) {
        if (d % 2 == 0) {
            // even diagonal: traverse from bottom to top
            int r = d < m ? d : m - 1;
            int c = d - r;
            while (r >= 0 && c < n) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // odd diagonal: traverse from top to bottom
            int r, c;
            if (d < n) {
                r = 0;
                c = d;
            } else {
                r = d - n + 1;
                c = n - 1;
            }
            while (r < m && c >= 0) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    // Step 1: find the largest index i such that digits[i] < digits[i + 1]
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    // If no such index exists, this is the highest permutation
    if (i < 0) {
        return -1;
    }
    // Step 2: find the largest index j greater than i such that digits[j] > digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Step 3: swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Step 4: reverse the suffix starting at i + 1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert the resulting digit array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // The resulting number is out of int range
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] temp = new char[n];
    char[] digits = {'0', '1', '6', '8', '9'};
    java.util.Map<Character, Character> mapping = new java.util.HashMap<>();
    mapping.put('0', '0');
    mapping.put('1', '1');
    mapping.put('6', '9');
    mapping.put('9', '6');
    mapping.put('8', '8');
    backtrack(n, 0, temp, digits, mapping, result);
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    long areaTwice = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
    return areaTwice != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be positive");
    }
    int[] ugly = new int[n];
    ugly[0] = 1; // first ugly number
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0; // no characters, energy is zero
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    // Check the last run
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, res);
    }
    return res;
}

private static void dfs(int curr, int n, List<Integer> res) {
    res.add(curr);
    long currLong = curr;
    for (int i = 0; i < 10; i++) {
        long next = currLong * 10 + i;
        if (next > n) break;
        dfs((int) next, n, res);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Base case: dp[0] is 0 (zero sum requires zero squares)
    dp[0] = 0;
    // Initialize dp[i] with the maximum possible value (i, using all 1's)
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int n = s.length();
    int i = 0;
    while (i < n) {
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            int j = i;
            while (j < n && s.charAt(j) != ' ') {
                j++;
            }
            String word = s.substring(i, j);
            result.append(new StringBuilder(word).reverse());
            i = j;
        }
    }
    return result.toString();
}
